            [3696769450586, 3696769450587],
            ["2017-02-22T16:24:10.586", "2017-02-22T16:24:10.587"],
        ),
        (
            "microseconds",
            [3696769450586123, 3696769450586124],
            ["2017-02-22T16:24:10.586123", "2017-02-22T16:24:10.586124"],
        ),
    ],
)
def test_decode_cf_datetime_precision(dtype, unit, offsets, expected):
    # Scaling distant offsets to nanoseconds as floats loses precision.
    num_dates = np.array(offsets, dtype=dtype).reshape(1, 2)
    expected = np.array(expected, dtype="datetime64[ns]").reshape(1, 2)
    actual = decode_cf_datetime(
        num_dates, unit + " since 1900-01-01", "proleptic_gregorian"
    )
